package org.example.backend.service;
import org.example.backend.entity.*;
import org.example.backend.mapper.*;
import org.example.backend.service.impl.*;
import org.junit.jupiter.api.Test;
import java.time.LocalDateTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ClientHeartbeatBehaviorTest {
    @Test void teacherHeartbeatValidatesAddressAndMarksFreshHostsOnline(){TeacherHostMapper mapper=mock(TeacherHostMapper.class);TeacherHostServiceImpl service=new TeacherHostServiceImpl(mapper);assertThrows(IllegalArgumentException.class,()->service.heartbeat(null));TeacherHostEntity host=new TeacherHostEntity();host.setLabId(1L);assertThrows(IllegalArgumentException.class,()->service.heartbeat(host));host.setTeacherDeviceId("pc");assertThrows(IllegalArgumentException.class,()->service.heartbeat(host));host.setHostIp("127.0.0.1");assertThrows(IllegalArgumentException.class,()->service.heartbeat(host));host.setPort(0);assertThrows(IllegalArgumentException.class,()->service.heartbeat(host));host.setPort(8000);assertSame(host,service.heartbeat(host));assertEquals("online",host.getStatus());assertNotNull(host.getLastHeartbeatTime());verify(mapper).upsertHeartbeat(host);when(mapper.selectCurrentByLabId(1L)).thenReturn(host);assertSame(host,service.currentHost(1L));verify(mapper,never()).markOffline(any(),any());}
    @Test void missingAndExpiredTeacherHostsAreNotReturnedAsOnline(){TeacherHostMapper mapper=mock(TeacherHostMapper.class);TeacherHostServiceImpl service=new TeacherHostServiceImpl(mapper);assertNull(service.currentHost(1L));TeacherHostEntity host=new TeacherHostEntity();host.setLabId(1L);host.setTeacherDeviceId("pc");host.setStatus("online");when(mapper.selectCurrentByLabId(1L)).thenReturn(host);assertNull(service.currentHost(1L));host.setStatus("online");host.setLastHeartbeatTime(LocalDateTime.now().minusMinutes(1));assertNull(service.currentHost(1L));assertEquals("offline",host.getStatus());verify(mapper,times(2)).markOffline("pc",1L);assertThrows(IllegalArgumentException.class,()->service.currentHost(0L));}
    @Test void studentLifecyclePreservesLabScopeAndToleratesNoRows(){StudentClientMapper mapper=mock(StudentClientMapper.class);StudentClientServiceImpl service=new StudentClientServiceImpl(mapper);StudentClientEntity client=new StudentClientEntity();assertThrows(IllegalArgumentException.class,()->service.online(null));assertThrows(IllegalArgumentException.class,()->service.offline(null));client.setLabId(1L);assertThrows(IllegalArgumentException.class,()->service.online(client));assertThrows(IllegalArgumentException.class,()->service.offline(client));client.setStudentDeviceId("pc");assertSame(client,service.online(client));assertEquals("online",client.getStatus());assertNotNull(client.getLastHeartbeatTime());service.offline(client);verify(mapper).upsertOnline(client);verify(mapper).markOffline("pc",1L);assertEquals(List.of(),service.listByLabId(1L));when(mapper.selectByLabId(1L)).thenReturn(List.of(client));assertEquals(List.of(client),service.listByLabId(1L));assertThrows(IllegalArgumentException.class,()->service.listByLabId(-1L));}
    @Test void reservationHandlerRetriesOnlyLockFailuresAndDelegatesReview(){DefaultReservationCreationService creation=mock(DefaultReservationCreationService.class);DefaultReservationReviewService review=mock(DefaultReservationReviewService.class);DefaultReservationCommandHandler handler=new DefaultReservationCommandHandler(creation,review);ReservationActor actor=ReservationActor.systemAdministrator(1);var command=new CreateReservationCommand("甲","学院","123",1L,java.time.LocalDate.now(),"08:00-10:00","教学",1,"测试");var failure=new org.springframework.dao.PessimisticLockingFailureException("locked");when(creation.create(command,actor)).thenThrow(failure).thenReturn(null);assertNull(handler.create(command,actor));verify(creation,times(2)).create(command,actor);doThrow(failure).when(creation).create(command,actor);assertThrows(org.springframework.dao.PessimisticLockingFailureException.class,()->handler.create(command,actor));verify(creation,times(5)).create(command,actor);handler.approve(new ReviewReservationCommand(1L,"同意"),actor);handler.reject(new ReviewReservationCommand(1L,"拒绝"),actor);verify(review).approve(any(),eq(actor));verify(review).reject(any(),eq(actor));}
}
